ALLOWED={'ACTION_STARTED':{'ACTION_RETURNED'},'ACTION_RETURNED':{'VERIFYING'},'VERIFYING':{'SUCCESS','FAILURE','INCONCLUSIVE'},'SUCCESS':{'TERMINAL'},'FAILURE':{'RECOVERY_PENDING'},'INCONCLUSIVE':{'RECOVERY_PENDING'},'RECOVERY_PENDING':{'RECOVERY_EXECUTING'},'RECOVERY_EXECUTING':{'REVERIFYING'},'REVERIFYING':{'RECOVERED','FAILED','INCONCLUSIVE'},'RECOVERED':{'TERMINAL'},'FAILED':{'TERMINAL'}}
def transition(src,dst):
    if dst not in ALLOWED.get(src,set()):raise ValueError(f'illegal transition {src}->{dst}')
    return dst
